AI.GGCBOJKCOMJ = BTNode  # base of every behaviour-tree node: Init(tree), ProcessUpdate pushes itself on tree.Running, calls the abstract update, pops when not Running
AI.GGCBOJKCOMJ::IKLNPCHBLCA = OnUpdate  # abstract per-node tick (bb, childResult) -> NodeStatus; every node overrides it
AI.GGCBOJKCOMJ::NCGAPHBBEDH = PushRunning  # first tick: _isRunning = true, tree.Running.Push(this)
AI.GGCBOJKCOMJ::GBPPPNNFHHD = PopRunning  # _isRunning = false, tree.Running.Pop()
AI.GGCBOJKCOMJ::ICHOACLBGAD = ResumeParent  # passes a finished result to tree.Running.Peek().ProcessUpdate
AI.GGCBOJKCOMJ::CMJIGFDFAGG = _isRunning  # set by PushRunning, cleared by PopRunning
AI.GGCBOJKCOMJ::KNAGEGMJPNB = _scheduler  # the IScheduler given to Init; its Running stack
AI.LECHLIEBBEM = BTNodeStatus  # NONE, Success, Fail, Running: every OnUpdate returns it
AI.CJJGGNNFNLJ = IScheduler  # interface of Scheduler (GMOGDMKPGKF), what SchedulerProcessor.GetSchedulerByID returns: IsEnabled, Running (node stack), Monitors, CurrentResult, OwnerSectorBody; Init(tree) on every node
AI.MNIJEDINGOI = AIBlackboard  # AgentShip.bb: Target, NavMarker, AgroList, Scratch, TimeSince[]; passed to every node's OnUpdate
AI.MNIJEDINGOI::IHMEALDOMKM = CreateMarkers  # ctor: spawns "<name>_NavMarker"/"_AvoidanceMarker"/"_ImpulseOrigin"/"_ImpulseDestination" AIMarker bodies
AI.NFFNHMHIMML = TimerType  # index into Blackboard.TimeSince: WeaponFire, Strafe, Orbit, HailStart, LKLStarted, ...
AI.GBEFAHLEGIO = BBTargetSlot  # which blackboard body a node acts on: Nav, Target, TempObject, Self, OrbitTarget, LKL, Tether, CurrentPatrolPoint, ...
AI.FICGAHGCLCB = Repeater  # ctor(count, child): reruns the child count times, forever when -1; every tree root is Repeater(-1, ...)
AI.FICGAHGCLCB::FNFCEIDDDBJ = _repeatCount  # ctor arg; -1 = forever
AI.FICGAHGCLCB::KFFJHEFLDCD = _iteration  # counts finished runs against _repeatCount
AI.FICGAHGCLCB::FACKKDKMLGP = _child  # the repeated node
